def load_summary() -> Dict[str, Any]:
    if not SUMMARY_JSON.exists():
        raise FileNotFoundError(f"Missing {SUMMARY_JSON}. Run scripts/aggregate.py first.")
    return json.loads(SUMMARY_JSON.read_text(encoding="utf-8"))


def find_row(rows: List[Dict[str, Any]], cfg: str) -> Dict[str, Any]:
    for r in rows:
        if r["config"] == cfg:
            return r
    raise KeyError(f"Config {cfg} not found in summary_rows")


def find_pair(pairs: List[Dict[str, Any]], a: str, b: str) -> Dict[str, Any]:
    for p in pairs:
        if (p["config_a"] == a and p["config_b"] == b) or (p["config_a"] == b and p["config_b"] == a):
            if p["config_a"] == a:
                return p
            return {
                "config_a": a,
                "config_b": b,
                "n_paired": p["n_paired"],
                "a_only_resolved_b": p["b_only_resolved_c"],
                "b_only_resolved_c": p["a_only_resolved_b"],
                "mcnemar_p_value": p["mcnemar_p_value"],
                "diff_pct": round(-p["diff_pct"], 2),
                "bootstrap_95_lo_pct": round(-p["bootstrap_95_hi_pct"], 2),
                "bootstrap_95_hi_pct": round(-p["bootstrap_95_lo_pct"], 2),
                "mean_peak_prompt_diff": round(-p["mean_peak_prompt_diff"], 1),
                "peak_diff_bootstrap_95_lo": round(-p["peak_diff_bootstrap_95_hi"], 1),
                "peak_diff_bootstrap_95_hi": round(-p["peak_diff_bootstrap_95_lo"], 1),
                "a_lower_peak_k": p["b_lower_peak_k"],
                "b_lower_peak_k": p["a_lower_peak_k"],
                "peak_sign_test_p_value": p["peak_sign_test_p_value"],
                "mean_cum_tokens_diff": round(-p["mean_cum_tokens_diff"], 1),
                "cum_tokens_diff_bootstrap_95_lo": round(-p["cum_tokens_diff_bootstrap_95_hi"], 1),
                "cum_tokens_diff_bootstrap_95_hi": round(-p["cum_tokens_diff_bootstrap_95_lo"], 1),
                "a_lower_cum_tokens_k": p["b_lower_cum_tokens_k"],
                "b_lower_cum_tokens_k": p["a_lower_cum_tokens_k"],
                "cum_tokens_sign_test_p_value": p["cum_tokens_sign_test_p_value"],
                "mean_duration_diff_sec": round(-p["mean_duration_diff_sec"], 2),
                "duration_diff_bootstrap_95_lo": round(-p["duration_diff_bootstrap_95_hi"], 2),
                "duration_diff_bootstrap_95_hi": round(-p["duration_diff_bootstrap_95_lo"], 2),
                "a_lower_duration_k": p["b_lower_duration_k"],
                "b_lower_duration_k": p["a_lower_duration_k"],
                "duration_sign_test_p_value": p["duration_sign_test_p_value"],
            }
    raise KeyError(f"Pair ({a}, {b}) not found in paired_tests")


def render_all() -> None:
    data = load_summary()
    rows = data["summary_rows"]
    pairs = data["paired_tests"]
    stage_stats = data.get("stage_reset_stats", {})
    prompt_buckets = data.get("prompt_length_buckets", [])
    rerun_rep = data.get("rerun_reproducibility", {})
    cohort_bk = data.get("cohort_breakdown", {})
    fail_tax = data.get("failure_taxonomy", {})
    task_matrix = data.get("task_matrix", [])

    r_starter = find_row(rows, "flat_starter")
    r_ctrl = find_row(rows, "flat_controlled")
    r_sfd = find_row(rows, "sfd")

    p_sfd_starter = find_pair(pairs, "sfd", "flat_starter")
    p_sfd_ctrl = find_pair(pairs, "sfd", "flat_controlled")

    n_tasks = r_sfd["n_tasks"]

    # Build Typst and Markdown main table rows
    typst_main_rows = []
    md_main_rows = []
    for cfg_key in ("flat_starter", "flat_controlled", "sfd"):
        r = find_row(rows, cfg_key)
        label = CONFIG_LABELS[cfg_key]
        no_patch_k = r["n_tasks"] - r["patches_generated_k"]
        wrong_patch_k = r["patches_generated_k"] - r["resolved_k"]
        typst_main_rows.append(
            f"  [{label}], [{r['resolved_k']}/{r['n_tasks']} ({r['resolved_pct']:.1f}%)], "
            f"[[{r['wilson_95_lo']:.1f}%, {r['wilson_95_hi']:.1f}%]], "
            f"[{r['patches_generated_k']}/{r['n_tasks']} ({r['patches_generated_pct']:.1f}%)], "
            f"[{no_patch_k} / {wrong_patch_k}], "
            f"[{r['mean_peak_prompt_tokens']:.1f}], [{r['max_peak_prompt_tokens']}], "
            f"[{r['mean_cumulative_total_tokens']:.1f}], [{r['mean_tool_calls']:.1f}], [{r['mean_duration_sec']:.1f}s],"
        )
        md_main_rows.append(
            f"| {label} | {r['resolved_k']}/{r['n_tasks']} ({r['resolved_pct']:.1f}%) | "
            f"[{r['wilson_95_lo']:.1f}%, {r['wilson_95_hi']:.1f}%] | "
            f"{r['patches_generated_k']}/{r['n_tasks']} ({r['patches_generated_pct']:.1f}%) | "
            f"{no_patch_k} / {wrong_patch_k} | "
            f"{r['mean_peak_prompt_tokens']:.1f} | {r['max_peak_prompt_tokens']} | "
            f"{r['mean_cumulative_total_tokens']:.1f} | {r['mean_tool_calls']:.1f} | {r['mean_duration_sec']:.1f}s |"
        )
    typst_main_table_body = "\n".join(typst_main_rows)
    md_main_table = "\n".join(md_main_rows)

    # Build Typst and Markdown per-task table rows
    typst_task_rows = []
    md_task_rows = []
    for tm in task_matrix:
        iid = tm["instance_id"]
        repo = tm.get("repo", "")
        st_res = "Pass" if tm.get("flat_starter_resolved") else f"Fail ({tm.get('flat_starter_failure_bucket', 'n/a').replace('_', ' ')})"
        ct_res = "Pass" if tm.get("flat_controlled_resolved") else f"Fail ({tm.get('flat_controlled_failure_bucket', 'n/a').replace('_', ' ')})"
        sf_res = "Pass" if tm.get("sfd_resolved") else f"Fail ({tm.get('sfd_failure_bucket', 'n/a').replace('_', ' ')})"
        st_res_m = "Pass" if tm.get("flat_starter_resolved") else f"Fail (`{tm.get('flat_starter_failure_bucket', 'n/a')}`)"
        ct_res_m = "Pass" if tm.get("flat_controlled_resolved") else f"Fail (`{tm.get('flat_controlled_failure_bucket', 'n/a')}`)"
        sf_res_m = "Pass" if tm.get("sfd_resolved") else f"Fail (`{tm.get('sfd_failure_bucket', 'n/a')}`)"
        st_pk = tm.get("flat_starter_peak_prompt_tokens", 0)
        ct_pk = tm.get("flat_controlled_peak_prompt_tokens", 0)
        sf_pk = tm.get("sfd_peak_prompt_tokens", 0)
        typst_task_rows.append(
            f"  [`{iid}`], [`{repo}`], [{st_res} ({st_pk})], [{ct_res} ({ct_pk})], [{sf_res} ({sf_pk})],"
        )
        md_task_rows.append(
            f"| `{iid}` | `{repo}` | {st_res_m} ({st_pk}) | {ct_res_m} ({ct_pk}) | {sf_res_m} ({sf_pk}) |"
        )
    typst_task_table_body = "\n".join(typst_task_rows)
    md_task_table = "\n".join(md_task_rows)

    # Stage reset stats & table
    triage_peak_mean = stage_stats.get("mean_triage_peak_prompt_tokens", 0.0)
    triage_peak_max = stage_stats.get("max_triage_peak_prompt_tokens", 0)
    patch_entry_mean = stage_stats.get("mean_patch_entry_prompt_tokens", 0.0)
    patch_entry_max = stage_stats.get("max_patch_entry_prompt_tokens", 0)
    patch_peak_mean = stage_stats.get("mean_patch_peak_prompt_tokens", 0.0)
    patch_peak_max = stage_stats.get("max_patch_peak_prompt_tokens", 0)
    verifier_entry_mean = stage_stats.get("mean_verifier_entry_prompt_tokens", 0.0)
    verifier_entry_max = stage_stats.get("max_verifier_entry_prompt_tokens", 0)
    verifier_peak_mean = stage_stats.get("mean_verifier_peak_prompt_tokens", 0.0)
    verifier_peak_max = stage_stats.get("max_verifier_peak_prompt_tokens", 0)
    triage_to_patch_red = stage_stats.get("mean_triage_to_patch_reduction_pct", 0.0)

    ca_stats = stage_stats.get("flat_starter_code_analyzer", {})
    ca_tasks_k = ca_stats.get("tasks_invoking_code_analyzer_k", 0)
    ca_bypass_k = ca_stats.get("tasks_bypassing_code_analyzer_k", 0)
    ca_bypass_pct = ca_stats.get("tasks_bypassing_code_analyzer_pct", 0.0)
    ca_calls = ca_stats.get("code_analyzer_calls", 0)
    ca_budget_tot = ca_stats.get("budget_counted_tool_calls_total", 71)
    ca_root_budget = ca_stats.get("root_budget_counted_calls", 64)
    ca_child_calls = ca_stats.get("child_code_analyzer_calls", 7)
    ca_free_submit = ca_stats.get("free_submit_patch_calls", 6)
    ca_root_decisions = ca_stats.get("root_non_submit_decisions", 66)
    ca_root_share = ca_stats.get("code_analyzer_root_decision_share_pct", 3.0)
    ca_tot_calls = ca_stats.get("total_recorded_tool_calls", 79)
    ca_share_pct = ca_stats.get("code_analyzer_call_share_pct", 2.5)

    per_task_stage = stage_stats.get("per_task", {})
    typst_stage_rows = []
    md_stage_rows = []
    for iid in sorted(per_task_stage.keys()):
        st = per_task_stage[iid]
        red_pct = round((1.0 - (st["patch_entry"] / st["triage_peak"])) * 100.0, 1) if st["triage_peak"] else 0.0
        typst_stage_rows.append(
            f"  [`{iid}`], [{st['triage_entry']}], [{st['triage_peak']}], [{st['patch_entry']} (-{red_pct:.1f}%)], [{st['patch_peak']}], [{st['verifier_entry']}], [{st['verifier_peak']}],"
        )
        md_stage_rows.append(
            f"| `{iid}` | {st['triage_entry']} | {st['triage_peak']} | {st['patch_entry']} (-{red_pct:.1f}%) | {st['patch_peak']} | {st['verifier_entry']} | {st['verifier_peak']} |"
        )
    typst_stage_table_body = "\n".join(typst_stage_rows)
    md_stage_table_body = "\n".join(md_stage_rows)

    # Prompt-length bucket table (Testing Hypothesis 1)
    prompt_buckets_by_cfg = data.get("prompt_length_buckets_by_config", {})
    typst_bucket_rows = []
    md_bucket_rows = []
    for b in prompt_buckets:
        bl_t = b["bucket"].replace(">=", "$>=$").replace("<", "$<$")
        typst_bucket_rows.append(
            f"  [{bl_t}], [{b['llm_calls']}], [{b['tool_calls']}], "
            f"[{b['tool_errors_non_budget']}/{b['tool_calls']} ({b['tool_error_non_budget_pct']:.1f}%)], "
            f"[{b['budget_errors']}/{b['tool_calls']}], "
            f"[{b['edit_file_errors']}/{b['edit_calls']} ({b['edit_file_error_pct']:.1f}%)], "
            f"[{b['edit_budget_errors']}/{b['edit_calls']}], "
            f"[{b['dup_reads']}/{b['read_calls']} ({b['dup_read_pct']:.1f}%)],"
        )
        md_bucket_rows.append(
            f"| `{b['bucket']}` | {b['llm_calls']} | {b['tool_calls']} | "
            f"{b['tool_errors_non_budget']}/{b['tool_calls']} ({b['tool_error_non_budget_pct']:.1f}%) | "
            f"{b['budget_errors']}/{b['tool_calls']} | "
            f"{b['edit_file_errors']}/{b['edit_calls']} ({b['edit_file_error_pct']:.1f}%) | "
            f"{b['edit_budget_errors']}/{b['edit_calls']} | "
            f"{b['dup_reads']}/{b['read_calls']} ({b['dup_read_pct']:.1f}%) |"
        )
    typst_bucket_table_body = "\n".join(typst_bucket_rows)
    md_bucket_table_body = "\n".join(md_bucket_rows)

    # Stratified per-config FileEditError rates across buckets
    typst_cfg_bucket_rows = []
    md_cfg_bucket_rows = []
    for cfg_k in ("flat_starter", "flat_controlled", "sfd"):
        cb_list = prompt_buckets_by_cfg.get(cfg_k, [])
        if len(cb_list) == 4:
            cells_t = [f"`{cfg_k}`"]
            cells_m = [f"`{cfg_k}`"]
            for cb in cb_list:
                cells_t.append(f"{cb['edit_file_errors']}/{cb['edit_calls']} ({cb['edit_file_error_pct']:.1f}%)")
                cells_m.append(f"{cb['edit_file_errors']}/{cb['edit_calls']} ({cb['edit_file_error_pct']:.1f}%)")
            typst_cfg_bucket_rows.append("  " + ", ".join(f"[{c}]" for c in cells_t) + ",")
            md_cfg_bucket_rows.append("| " + " | ".join(cells_m) + " |")
    typst_cfg_bucket_body = "\n".join(typst_cfg_bucket_rows)
    md_cfg_bucket_body = "\n".join(md_cfg_bucket_rows)

    # Unresolved SFD task audit table (Reviewer Point #1 & #2)
    typst_audit_rows = []
    md_audit_rows = []
